/**
 * Nuxt のモジュールと Vite のプラグインが、rouar.json からエージェントの経路を読む。
 * 開発のときの中継と、ブラウザの会話の URL の接頭辞に使う
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import {
	DEFAULT_AGENT_ROUTES,
	parseRouarConfig,
	ROUAR_CONFIG_FILE,
} from "./config";

/** 手元の Flue の開発のサーバーの既定。Flue の開発のサーバーは Vite の既定のポートで動く */
export const DEFAULT_AGENT_DEV_URL = "http://localhost:5173";

/** start から上へたどって rouar.json を探す。.git のあるディレクトリで止める */
export function findRouarConfig(start: string): string | undefined {
	let dir = start;
	for (;;) {
		const candidate = join(dir, ROUAR_CONFIG_FILE);
		if (existsSync(candidate)) return candidate;
		if (existsSync(join(dir, ".git"))) return undefined;
		const parent = dirname(dir);
		if (parent === dir) return undefined;
		dir = parent;
	}
}

/** 接頭辞を / で始まり / で終わらない形にそろえる。合わない値は例外にする */
export function normalizeAgentRoute(route: unknown, where: string): string {
	if (typeof route !== "string" || !route.startsWith("/")) {
		throw new Error(
			`[rouar] ${where} must be a path that starts with "/", got ${JSON.stringify(route)}.`,
		);
	}
	const trimmed = route.replace(/\/+$/, "");
	if (!trimmed || /[?#\s]/.test(trimmed)) {
		throw new Error(
			`[rouar] ${where} must be a path prefix such as "/agents", got ${JSON.stringify(route)}.`,
		);
	}
	return trimmed;
}

/**
 * エージェントの経路の接頭辞を決める。渡した値を先に使い、なければ rouar.json の agent.routes を読む。
 * どちらもなければ既定の /agents を返す
 */
export function resolveAgentRoutes(
	start: string,
	explicit?: readonly string[],
): string[] {
	if (explicit) {
		if (explicit.length === 0) {
			throw new Error("[rouar] agentRoutes must not be empty.");
		}
		return explicit.map((route) => normalizeAgentRoute(route, "agentRoutes"));
	}
	const path = findRouarConfig(start);
	if (!path) return [...DEFAULT_AGENT_ROUTES];
	// ワーカーと同じ schema で確かめ、デプロイで断られる設定を手元でも断る
	const parsed = parseRouarConfig(readFileSync(path, "utf8"));
	if (!parsed.success) {
		const details = parsed.issues
			.map((issue) => `${issue.path || "(root)"}: ${issue.message}`)
			.join("; ");
		throw new Error(`[rouar] ${path} is invalid: ${details}`);
	}
	const routes = parsed.config.agent?.routes ?? DEFAULT_AGENT_ROUTES;
	return routes.map((route) =>
		normalizeAgentRoute(route, `agent.routes in ${path}`),
	);
}

/** 開発のときの中継先。ROUAR_AGENT_DEV_URL があればそれを使う */
export function resolveAgentDevUrl(
	env: Record<string, string | undefined> = process.env,
): string {
	const value = env.ROUAR_AGENT_DEV_URL?.trim() || DEFAULT_AGENT_DEV_URL;
	let url: URL;
	try {
		url = new URL(value);
	} catch {
		throw new Error(
			`[rouar] ROUAR_AGENT_DEV_URL must be an http or https URL, got ${JSON.stringify(value)}.`,
		);
	}
	if (url.protocol !== "http:" && url.protocol !== "https:") {
		throw new Error(
			`[rouar] ROUAR_AGENT_DEV_URL must be an http or https URL, got ${JSON.stringify(value)}.`,
		);
	}
	return url.origin;
}

/** ブラウザで会話の URL の接頭辞を決めるスクリプト。Symbol の鍵は @rouar/sdk/client と同じ */
export function clientConfigScript(agentRoute: string): string {
	return `globalThis[Symbol.for("rouar.sdk.client")]=Object.assign(globalThis[Symbol.for("rouar.sdk.client")]||{},{agentRoute:${JSON.stringify(agentRoute).replace(/</g, "\\u003c")}});`;
}
